const content = $input.item.json.data || '';
const question = $('Extract File Info').item.json.question;
const wordCount = content.split(' ').length;
const truncated = wordCount > 3000 ? content.split(' ').slice(0, 3000).join(' ') + '...[truncated]' : content;
return [{ json: { content: truncated, question, word_count: wordCount, was_truncated: wordCount > 3000, session_id: $('Extract File Info').item.json.session_id } }];

const raw = $input.item.json.text.replace(/```json|```/g,'').trim();
const data = JSON.parse(raw);
return [{ json: { ...data, session_id: $('Check Content Length').item.json.session_id, word_count: $('Check Content Length').item.json.word_count } }];
